def run(context):
    # Filter VCP stocks
    vcp_stocks = context['scores.stage2_vcp_picks']
    candidates = [stock for stock in vcp_stocks if stock['vcp_score'] > 80 and stock['enhanced_fund_score'] > 70]
    return {'candidates': candidates}

def run(context):
    # Ensure 'latest_run_metadata' and 'filtered_stock_data' are not empty
    if not context.get('latest_run_metadata') or not context.get('filtered_stock_data'):
        return {'verified_findings': 'Data missing in the latest run.'}
    return {'verified_findings': 'All data present and accounted for in the latest run.'}

def run(context):
    holdings = context.get('holdings_data', [])
    trends = context.get('trend_signals', {})
    add_candidates = [h['symbol'] for h in holdings if trends.get(h['symbol'], {}).get('trend_signal') == 'Strong Uptrend']
    trim_candidates = [h['symbol'] for h in holdings if trends.get(h['symbol'], {}).get('trend_signal') == 'Downtrend']
    return {'add_candidates': add_candidates, 'trim_candidates': trim_candidates}
